'use strict';

// MODULES //

var dtypes = require( '@stdlib/ndarray/dtypes' );
var gaxpb = require( '@stdlib/blas/ext/base/ndarray/gaxpb' );
var daxpb = require( '@stdlib/blas/ext/base/ndarray/daxpb' );
var saxpb = require( '@stdlib/blas/ext/base/ndarray/saxpb' );
var caxpb = require( '@stdlib/blas/ext/base/ndarray/caxpb' );
var zaxpb = require( '@stdlib/blas/ext/base/ndarray/zaxpb' );
var factory = require( '@stdlib/ndarray/base/nullary-strided1d-dispatch-factory' );


// VARIABLES //

var idtypes0 = dtypes( 'numeric_and_generic' ); // alpha ndarray
var idtypes1 = dtypes( 'numeric_and_generic' ); // beta ndarray
var odtypes = dtypes( 'numeric_and_generic' );
var table = {
	'types': [
		'float64',    // input/output
		'float32',    // input/output
		'complex128', // input/output
		'complex64'   // input/output
	],
	'fcns': [
		daxpb,
		saxpb,
		zaxpb,
		caxpb
	],
	'default': gaxpb
};


// MAIN //

/**
* Multiplies each element in an input ndarray by a scalar constant and adds a scalar constant to each result along one or more ndarray dimensions.
*
* @private
* @name axpb
* @type {Function}
* @param {ndarray} x - input ndarray
* @param {ndarray} alpha - ndarray containing the scalar constant to multiply
* @param {ndarray} beta - ndarray containing the scalar constant to add
* @param {Options} [options] - function options
* @param {IntegerArray} [options.dims] - list of dimensions over which to perform operation
* @throws {TypeError} first argument must be an ndarray-like object
* @throws {TypeError} second argument must be an ndarray-like object
* @throws {TypeError} third argument must be an ndarray-like object
* @throws {TypeError} options argument must be an object
* @throws {RangeError} dimension indices must not exceed input ndarray bounds
* @throws {RangeError} number of dimension indices must not exceed the number of input ndarray dimensions
* @throws {Error} must provide valid options
* @returns {ndarray} output ndarray
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
* var ndarray = require( '@stdlib/ndarray/ctor' );
*
* // Create a data buffer:
* var xbuf = new Float64Array( [ -2.0, 1.0, 3.0, -5.0, 4.0, 0.0, -1.0, -3.0 ] );
*
* // Define the shape of the input array:
* var sh = [ 2, 2, 2 ];
*
* // Define the array strides:
* var sx = [ 4, 2, 1 ];
*
* // Define the index offset:
* var ox = 0;
*
* // Create an input ndarray:
* var x = new ndarray( 'float64', xbuf, sh, sx, ox, 'row-major' );
*
* // Create ndarrays containing the scalar constants:
* var alpha = scalar2ndarray( 5.0, {
*     'dtype': 'float64'
* });
*
* var beta = scalar2ndarray( 3.0, {
*     'dtype': 'float64'
* });
*
* // Perform operation:
* var out = axpb( x, alpha, beta );
* // returns <ndarray>[ [ [ -7.0, 8.0 ], [ 18.0, -22.0 ] ], [ [ 23.0, 3.0 ], [ -2.0, -12.0 ] ] ]
*/
var axpb = factory( table, [ idtypes0, idtypes1 ], odtypes );


// EXPORTS //

module.exports = axpb;
